import requests
import time


def fetch(url):
    max_retries = 3
    base_delay = 1  # seconds

    for attempt in range(max_retries + 1):
        try:
            r = requests.get(url, timeout=5)
            r.raise_for_status()
            return r.json()
        except (requests.Timeout, requests.ConnectionError) as e:
            if attempt < max_retries:
                delay = base_delay * (2 ** attempt)
                time.sleep(delay)
            else:
                raise
        except Exception:
            raise
